// WF27: leads directos de EasyBroker (Lamudi, Pincali, MLS, web...) -> V3.
// Inmuebles24 ya entra por Tokko (WF25); Instagram queda fuera (Marusa, 13-oct).
// v3_tokko_intake es idempotente por 'eb:<id>', asi que releer la misma solicitud no duplica.
const START = Date.parse('2026-10-15T06:00:00Z'); // sin backfill de antes de la salida
const since = Math.max(START, Date.now() - 6 * 3600 * 1000);
const e164 = (raw) => {
  const s = String(raw || '').trim();
  const d = s.replace(/\D/g, '');
  if (s.startsWith('+') && /^[1-9]\d{7,14}$/.test(d)) return '+' + d;
  if (/^\d{10}$/.test(d)) return '+52' + d;
  if (/^52\d{10}$/.test(d)) return '+' + d;
  return null;
};
const rows = $input.first().json.content || [];
return rows
  .filter((r) => !/inmuebles24|instagram|^\s*ig\s*$/i.test(String(r.source || '')))
  .filter((r) => Date.parse(r.happened_at) >= since && /^EB-[A-Z0-9]{4,}$/i.test(String(r.property_id || '')))
  .map((r) => ({ json: {
    eb_request_id: r.id,
    source: r.source || 'EasyBroker',
    name: r.name || null,
    phone: e164(r.phone),
    email: String(r.email || '').trim().toLowerCase() || null,
    property_id: String(r.property_id).toUpperCase(),
    message: String(r.message || '').replace(/\s+/g, ' ').trim().slice(0, 2000) || null,
  } }))
  .filter((x) => x.json.phone || x.json.email);
